/* ===========================================================================
   0146 — AI-DRAFTED QUESTIONS FOR THE 46 EMPTY MODULES. NOTHING PUBLISHES.
   ===========================================================================

   After 0145, 46 filmed modules carry no questions: Setting up the MPI (9),
   Success Cycle (12), Overcoming Objections modules 3-12 (10), Name Tag (8 —
   Parts 1 and 9 got the CSI seven), Menus (7 lesson modules; the two closers
   carry no quiz by ruling). The standing rule is AI drafts from the lesson,
   Mitch approves in admin, nothing serves until published.

   Every question below was drafted from the FILM'S OWN TRANSCRIPT (whisper
   small.en, 30 Sep 2026, from the published masters) — never from the title,
   never from general knowledge. 4 per module, 184 total: two Multiple Choice,
   one True/False, one scenario in the bank's existing "What Do You Say Next"
   shape. `correct` position is as authored; the quiz page shuffles options
   per advisor per attempt, so the stored letter is not a tell.

     status      'draft'         — moduleRequirementsMet ignores drafts, the
                                   quiz page serves only published, so NOTHING
                                   an advisor sees changes until Mitch acts
     source      'ai_generated'  — provenance, distinguishable from 'authored'
     deck        the track name
     film        the slate title, as "Part N — <spoken title>" (Menus: the
                 film's catalog title)
     module_id + content_id       joined on the film's exact TITLE — the only
                                   key both systems observed

   THERE IS NO ADMIN SCREEN FOR REVIEWING DRAFT QUESTIONS (checked 30 Sep: no
   route under /admin touches quiz_question). Until one exists, the review
   surface is reports/quiz-drafts-<track>.md, generated from these rows.

   On a fresh local none of the films exist and this is a quiet no-op.
   =========================================================================== */

create temporary table _aid (
  source_id  text,
  deck       text,
  film       text,
  film_title text,
  qtype      text,
  question   text,
  option_a   text,
  option_b   text,
  option_c   text,
  option_d   text,
  correct    char(1),
  explanation text,
  qno        int
);

/* ---- SETTING UP THE MPI — Get the Hell Out of Here, Parts 1-9 ---------- */

/* ---- MENUS — the seven lesson modules ----------------------------------- */

/* ---- SUCCESS CYCLE — Parts 1-12 ----------------------------------------- */

/* ---- OVERCOMING OBJECTIONS — modules 3-12, the Selling Skills films ------ */

/* ---- NAME TAG — Parts 2-8 and 10 (1 and 9 carry the CSI seven) ---------- */

/* ===========================================================================
   STAGE -> BANK, WITH THE GUARDS
   =========================================================================== */
do $$
declare
  _n int;
  _r record;
begin
  select count(*) into _n from _aid;
  if _n <> 184 then
    raise exception '0146: staged % rows, expected 184 (46 modules x 4)', _n;
  end if;

  /* Local replay: the films are not there, and this is a quiet no-op. */
  if not exists (select 1 from content
                  where title = 'Get the Hell Out of Here, Part 1'
                    and type = 'advisor_video' and status = 'published'
                    and retired_at is null and module_id is not null) then
    raise notice '0146: the routed films are not present on this database — nothing to do';
    return;
  end if;

  /* Idempotent on source_id, 0140''s way. */
  select count(*) into _n from quiz_question where source_id like 'AID:%';
  if _n = 184 then
    raise notice '0146: all 184 drafts already present — nothing to add';
    return;
  end if;
  if _n <> 0 then
    raise exception '0146: % of 184 already present — refusing a partial re-import', _n;
  end if;

    source_id, deck, film, question, option_a, option_b, option_c, option_d,
    correct, explanation, sort_order, status, source, question_type,
    shared_pool, module_id, content_id
  )
  select a.source_id, a.deck, a.film, a.question,
         a.option_a, a.option_b, a.option_c, a.option_d,
         a.correct, a.explanation, a.qno, 'draft', 'ai_generated', a.qtype,
         false, c.module_id, c.id
    from _aid a
    join content c
      on c.title = a.film_title
     and c.type = 'advisor_video'
     and c.status = 'published'
     and c.retired_at is null
     and c.module_id is not null;

  get diagnostics _n = row_count;
  if _n <> 184 then
    raise exception '0146: inserted % rows, expected 184 — a film title failed to join', _n;
  end if;

  /* ---- ASSERT, BOTH DIRECTIONS ------------------------------------------ */

  /* exactly 4 per module, over exactly 46 modules */
  select count(*) into _n from (
    select module_id from quiz_question where source_id like 'AID:%'
    group by module_id having count(*) <> 4
  ) bad;
  if _n <> 0 then
    raise exception '0146: % module(s) did not receive exactly 4 drafts', _n;
  end if;
  select count(distinct module_id) into _n from quiz_question where source_id like 'AID:%';
  if _n <> 46 then
    raise exception '0146: drafts landed on % modules, expected 46', _n;
  end if;

  /* every draft''s module is its film''s module */
  select count(*) into _n
    from quiz_question q join content c on c.id = q.content_id
   where q.source_id like 'AID:%' and c.module_id is distinct from q.module_id;
  if _n <> 0 then
    raise exception '0146: % draft(s) point at a different module than their film', _n;
  end if;

  /* NOTHING PUBLISHED. The bank the advisors see is exactly what 0145 left. */
  select count(*) into _n from quiz_question where status = 'published';
  if _n <> 112 then
    raise exception '0146: published count moved to % — drafts must not publish', _n;
  end if;
  select count(*) into _n from quiz_question
   where source_id like 'AID:%' and (status <> 'draft' or source <> 'ai_generated');
  if _n <> 0 then
    raise exception '0146: % draft row(s) with wrong status or source', _n;
  end if;

  /* every module set carries at least one scenario question */
  select count(*) into _n from (
    select module_id from quiz_question where source_id like 'AID:%'
    group by module_id
    having count(*) filter (where question_type = 'What Do You Say Next') = 0
  ) noscenario;
  if _n <> 0 then
    raise exception '0146: % module(s) have no scenario question', _n;
  end if;

  raise notice '0146: 184 drafts staged for Mitch — 36 Setting up the MPI, 48 Success Cycle, 40 Overcoming Objections, 32 Name Tag, 28 Menus. Nothing published.';
end
$$;
